def solve():
    memo_A = {}
    memo_B = {}

    def get_A(lengths):
        lengths = tuple(sorted([l for l in lengths if l > 1], reverse=True))
        if not lengths:
            return 0
        if lengths in memo_A:
            return memo_A[lengths]

        res = float('inf')
        for i, l in enumerate(lengths):
            for j in range(1, l):
                # Placing a tile at (j, j+1) in a segment of length l
                # results in two new segments of lengths j-1 and l-j-1
                new_lengths = list(lengths[:i] + lengths[i+1:])
                new_lengths.append(j - 1)
                new_lengths.append(l - j - 1)
                res = min(res, 1 + get_B(tuple(sorted([x for x in new_lengths if x > 1], reverse=True))))

        memo_A[lengths] = res
        return res

    def get_B(lengths):
        lengths = tuple(sorted([l for l in lengths if l > 1], reverse=True))
        if not lengths:
            return 0
        if lengths in memo_B:
            return memo_B[lengths]

        res = float('-inf')
        for i, l in enumerate(lengths):
            for j in range(1, l):
                new_lengths = list(lengths[:i] + lengths[i+1:])
                new_lengths.append(j - 1)
                new_lengths.append(l - j - 1)
                res = max(res, 1 + get_A(tuple(sorted([x for x in new_lengths if x > 1], reverse=True))))

        memo_B[lengths] = res
        return res

    for n in range(1, 21):
        k = get_A((n,))
        print(f"n={n}, k={k}, U={n-2*k}")

solve()
